-- Topaz frame interpolation on fal.ai (topaz/interpolate/video), verified against fal's published
-- schema: video_url plus model (Apollo/Chronos/Aion), slowdown_factor (1-8), target_fps (16-120),
-- H264_output. Post-production uses it to slow a shot down with the missing frames generated by a
-- model rather than computed by ffmpeg. Response is fal's common {video: {url}} envelope.
INSERT INTO model_master (model_id, provider_id, type, capabilities, context_window, supports_streaming, status, default_rpm, default_tpm, timeout_ms)
VALUES ('topaz/interpolate/video', 'fal.ai', 'interpolate', '{"frameInterpolation": true, "maxSlowdownFactor": 8}'::jsonb,
        NULL, false, 'active', 10, 1000000, 1200000);

-- Same placeholder as every fal.ai video-family model: real per-call pricing needs its own
-- rate_card shape (Topaz bills per generated frame), not fabricated here.
INSERT INTO rate_card (model_id, input_token_cost, output_token_cost, currency, effective_from)
VALUES ('topaz/interpolate/video', 0, 0, 'USD', now());

-- Upscaling a whole film takes minutes, not the 3 a single clip was given.
UPDATE model_master SET timeout_ms = 1200000 WHERE model_id = 'fal-ai/topaz/upscale/video';
